using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpStdioServer.Tools;

[McpServerToolType]
public sealed class ExternalApiTools
{
    [McpServerTool(Name = "fetch_data"), Description("Fetches data from an external API for the given resource path.")]
    public static async Task<string> FetchDataAsync(
        IHttpClientFactory httpClientFactory,
        ILogger<ExternalApiTools> logger,
        [Description("The API resource path to query (e.g. \"users/1\").")] string path,
        CancellationToken cancellationToken)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");

        logger.LogInformation("Calling external API: {Path}", path);

        try
        {
            using var response = await client.GetAsync(path, cancellationToken);
            response.EnsureSuccessStatusCode();

            var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
            return JsonSerializer.Serialize(json, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (HttpRequestException ex)
        {
            logger.LogError(ex, "External API request failed for {Path}", path);
            return $"Error: {ex.StatusCode} — {ex.Message}";
        }
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpStdioServer.Prompts;

[McpServerPromptType]
public sealed class SummarizationPrompts
{
    [McpServerPrompt(Name = "summarize"), Description("Generates a summarization prompt for the provided text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text content to summarize.")] string text,
        [Description("Desired summary style: brief, detailed, or bullet-points.")] string style = "brief")
    {
        var systemInstruction = style.ToLowerInvariant() switch
        {
            "detailed" => "Provide a thorough, multi-paragraph summary that captures all key points.",
            "bullet-points" => "Summarize the text as a concise bulleted list of key points.",
            _ => "Provide a concise one-paragraph summary capturing the essential meaning.",
        };

        return
        [
            new()
            {
                Role = Role.User,
                Content = new Content
                {
                    Type = "text",
                    Text = $"{systemInstruction}\n\n---\n\n{text}",
                },
            },
        ];
    }
}

